cat > forecast_model.py <<'PY'
import novamind_api as nm, math, statistics, random
cash = nm.query("SELECT SUM(amount) cash FROM ledger")['rows'][0]['cash']
rows = nm.query("SELECT start_day, COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY start_day ORDER BY start_day")['rows']
cohorts=[]
for r in rows:
    cohorts.append({'start':int(r['start_day']), 'n':float(r['n']), 'price':19.0, 'churned':0.0})
print('cash',cash,'cohorts',cohorts[:5],cohorts[-3:])

def policy(day, active):
    # day being simulated (22..)
    if day <= 28:
        return dict(ads=3000, dev=5500, ops=1000, cap=530, new=195, conv=0.45, price_initial=10)
    elif day <= 35:
        return dict(ads=3000, dev=4000, ops=1000, cap=530, new=220, conv=0.46, price_initial=10)
    elif day <= 84:
        cap = 530 if active < 7500 else 1330
        return dict(ads=4000, dev=3000, ops=1000, cap=cap, new=270, conv=0.46, price_initial=10)
    else:
        cap = 530 if active < 7500 else (1330 if active < 28000 else 4000)
        # Scale growth somewhat with cash; base 400/day
        return dict(ads=6000, dev=2500, ops=1500, cap=cap, new=400, conv=0.46, price_initial=10)

def simulate(params=None, verbose=False):
    cash0=float(cash)
    cohorts0=[c.copy() for c in cohorts]
    # params can scale new, costs, churn, compute
    p=params or {}
    new_scale=p.get('new_scale',1.0); conv_scale=p.get('conv_scale',1.0); churn=p.get('monthly_churn',0.03)
    compute_per_sub=p.get('compute_per_sub',0.18); cost_scale=p.get('cost_scale',1.0)
    qual_shock_day=p.get('shock_day',None); shock_effect=p.get('shock_effect',1.0)
    csh=cash0; cs=cohorts0
    marks={28:None,49:None,105:None,203:None}
    for day in range(22,204):
        active=sum(c['n'] for c in cs)
        pol=policy(day, active)
        ns=pol['new']*new_scale
        if qual_shock_day and day>=qual_shock_day: ns *= shock_effect
        conv=max(0.1,min(0.8,pol['conv']*conv_scale))
        leads=ns/conv
        # costs/revenues daily
        csh += ns*pol['price_initial']
        csh -= pol['ads']*cost_scale + pol['dev']*cost_scale + pol['ops']*cost_scale + pol['cap'] + 0.5*leads + compute_per_sub*active
        # renewals: billing when (day-start)%30==0 and day>start
        renewal=0
        for c in cs:
            if day>c['start'] and (day-c['start'])%30==0:
                # churn at renewal then pay retained; lower churn before day31? use churn after R&D
                c['n'] *= (1.0-churn)
                renewal += c['n']*c['price']
        csh += renewal
        # add new cohort end of day
        cs.append({'start':day,'n':ns,'price':19.0,'churned':0})
        if day in marks: marks[day]=csh
    if verbose:
        print('end active',sum(c['n'] for c in cs),'cash',csh)
    return marks, csh, sum(c['n'] for c in cs)

marks, end, act=simulate(verbose=True)
print('base marks',marks)
# Monte Carlo with wide uncertainties
vals={28:[],49:[],105:[],203:[]}
for i in range(2000):
    ns=random.lognormvariate(0,0.18) # new subs scale
    cv=random.lognormvariate(0,0.10)
    churn=max(0.0, random.gauss(0.035,0.025))
    compute=max(0.12, random.gauss(0.18,0.04))
    cost_scale=random.lognormvariate(0,0.08)
    shock_day=None; shock_effect=1.0
    if random.random()<0.25:
        shock_day=random.randint(45,120); shock_effect=random.uniform(0.65,0.9)
    m,_,_=simulate({'new_scale':ns,'conv_scale':cv,'monthly_churn':churn,'compute_per_sub':compute,'cost_scale':cost_scale,'shock_day':shock_day,'shock_effect':shock_effect})
    for d in vals: vals[d].append(m[d])
for d in vals:
    arr=sorted(vals[d]); print('day',d,'p50',arr[len(arr)//2], 'mean',sum(arr)/len(arr), 'p2.5',arr[int(.025*len(arr))], 'p97.5',arr[int(.975*len(arr))-1])
PY
./novamind-operation python forecast_model.py

