import json, statistics
import novamind_api as nm

def q(sql):
    try:
        return nm.query(sql).get('rows', [])
    except Exception as e:
        return [{'ERROR': str(e), 'sql': sql}]

def show(title, rows, max_rows=20):
    print(f"\n## {title}")
    if isinstance(rows, (dict, list)):
        if isinstance(rows, dict):
            print(json.dumps(rows, indent=2, default=str)[:4000])
        else:
            for r in rows[:max_rows]:
                print(r)
            if len(rows)>max_rows: print(f"... {len(rows)-max_rows} more")
    else: print(rows)

print('day', nm.vars.current_day)
show('ledger by category day>=0', q("SELECT category, COUNT(*) n, ROUND(SUM(amount),2) amount FROM ledger GROUP BY category ORDER BY amount"))
show('ledger by day/category last 14', q("SELECT day, category, ROUND(SUM(amount),2) amount FROM ledger WHERE day>=0 GROUP BY day,category ORDER BY day,category"), 200)
show('cash', q("SELECT ROUND(SUM(amount),2) cash FROM ledger"))
show('ad channel leads', q("SELECT channel_id, group_id, SUM(leads_generated) leads, ROUND(SUM(spend),2) spend, ROUND(1000.0*SUM(leads_generated)/NULLIF(SUM(spend),0),2) leads_per_1000 FROM ad_channel_leads GROUP BY channel_id,group_id ORDER BY group_id, leads DESC"), 100)
show('customers by group/source/status', q("""
SELECT c.group_id, c.acquisition_source, c.customer_type, s.status, COUNT(*) n,
       SUM(CASE WHEN s.plan='A' THEN 1 ELSE 0 END) A,
       SUM(CASE WHEN s.plan='B' THEN 1 ELSE 0 END) B,
       SUM(CASE WHEN s.plan='C' THEN 1 ELSE 0 END) C,
       ROUND(AVG(CASE WHEN s.status='subscribed' THEN s.effective_price END),2) avg_eff,
       ROUND(SUM(CASE WHEN s.status='subscribed' THEN s.effective_price*s.seat_count ELSE 0 END),2) mrr_active
FROM customers c JOIN subscriptions s ON c.customer_id=s.customer_id
GROUP BY c.group_id,c.acquisition_source,c.customer_type,s.status
ORDER BY c.group_id,c.acquisition_source,s.status
"""), 200)
show('active subs by group plan', q("""
SELECT c.group_id, s.plan, COUNT(*) n, SUM(s.seat_count) seats, ROUND(AVG(s.listed_price),2) avg_listed, ROUND(AVG(s.promotion),2) avg_promo, ROUND(AVG(s.effective_price),2) avg_eff, ROUND(SUM(s.effective_price*s.seat_count),2) monthly_rev
FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id
WHERE s.status='subscribed'
GROUP BY c.group_id, s.plan ORDER BY c.group_id, s.plan
"""),100)
show('lost leads by group', q("SELECT c.group_id, COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='lost' GROUP BY c.group_id"))
show('created by day/group/status', q("""
SELECT c.created_day, c.group_id, s.status, COUNT(*) n FROM customers c JOIN subscriptions s ON c.customer_id=s.customer_id
GROUP BY c.created_day,c.group_id,s.status ORDER BY c.created_day,c.group_id,s.status
"""), 200)
show('service day', q("SELECT * FROM service_day ORDER BY day"), 50)
show('daily usage aggregate', q("SELECT day, COUNT(*) active_users, SUM(usage_units) usage FROM daily_usage GROUP BY day ORDER BY day"), 50)
show('issues', q("SELECT status, group_id, COUNT(*) n, AVG(days_open) avg_days FROM issues GROUP BY status, group_id"), 100)
show('pending enterprise latest', q("""
SELECT et.* FROM enterprise_turns et JOIN (SELECT customer_id, MAX(message_id) mid FROM enterprise_turns WHERE closed=0 GROUP BY customer_id) x ON et.message_id=x.mid WHERE et.sender='customer' ORDER BY day LIMIT 50
"""),100)
