queries={
'ad leads recent':\"SELECT channel_id, group_id, SUM(leads_generated) leads, ROUND(SUM(spend),2) spend, ROUND(SUM(spend)/NULLIF(SUM(leads_generated),0),2) cost_per_lead FROM ad_channel_leads WHERE day BETWEEN 29 AND 35 GROUP BY channel_id, group_id\",
'created day source week5':\"SELECT c.created_day,c.acquisition_source,c.group_id,s.status,COUNT(*) n FROM customers c JOIN subscriptions s ON c.customer_id=s.customer_id WHERE c.created_day BETWEEN 29 AND 35 GROUP BY c.created_day,c.acquisition_source,c.group_id,s.status ORDER BY c.created_day,c.acquisition_source,s.status\",
'source week5 aggregate':\"SELECT c.acquisition_source,c.group_id,s.status,COUNT(*) n FROM customers c JOIN subscriptions s ON c.customer_id=s.customer_id WHERE c.created_day BETWEEN 29 AND 35 GROUP BY c.acquisition_source,c.group_id,s.status ORDER BY c.group_id,c.acquisition_source,s.status\",
'issues open ages':\"SELECT open_day, days_open, group_id, COUNT(*) n FROM issues WHERE status='open' GROUP BY open_day,days_open,group_id ORDER BY open_day\",
'issues by day status':\"SELECT open_day, status, COUNT(*) n, AVG(days_open) avgdays FROM issues GROUP BY open_day,status ORDER BY open_day\",
'usage by plan week':\"SELECT s.plan,c.group_id,COUNT(*) records,COUNT(DISTINCT u.customer_id) users,SUM(u.usage_units) usage,ROUND(AVG(u.usage_units),1) avg_usage_record FROM daily_usage u JOIN subscriptions s ON u.customer_id=s.customer_id JOIN customers c ON c.customer_id=s.customer_id WHERE u.day BETWEEN 29 AND 35 AND s.status='subscribed' GROUP BY s.plan,c.group_id ORDER BY c.group_id,s.plan\"
}
for title,sql in queries.items():
 print('\n##',title)
 for row in nm.query(sql)['rows']: print(row)
"

