import novamind_api as nm
print('day', nm.vars.current_day)
# Clear any targeted ops with legacy argument; docs mention by_group but current API accepts targeted_spend only.
try:
    print(nm.analytics.set_targeted_ops_spend(targeted_spend={}))
except Exception as e:
    print('targeted_ops_clear_error', e)
print(nm.marketing.set_targeted_ad_spend(targeted_spend={
    "content_marketing": {"S1": 4500.0},
