arguments.old_string:
# Budget for one week of growth without jumping to the next tier too early.
# Actual S1 usage has averaged ~75-85 units/day/sub; tier3 covers ~25k-30k
# S1 subs comfortably.  Use recent peak*2 and 140 units/sub as a balanced
# rule, while forcing tier3 once the base is several thousand users.
if nsubs > 6000:
    need = max(usage * 2.0, nsubs * 140.0, 800001.0)
elif nsubs > 500:
    need = max(usage * 2.0, nsubs * 140.0)
else:
    need = max(usage * 1.5, nsubs * 160.0)

arguments.new_string:
# Budget for one week of growth without jumping to the next tier too early.
# Actual S1 usage has averaged ~75-85 units/day/sub.  For early scale keep
# 2x headroom; once above ~20k subs use a leaner high-tier rule so we don't
# jump to tier5 while tier4 still has ample week-ahead capacity.
if nsubs > 20000:
    need = max(usage * 1.6, nsubs * 120.0, 800001.0)
elif nsubs > 6000:
    need = max(usage * 2.0, nsubs * 140.0, 800001.0)
elif nsubs > 500:
    need = max(usage * 2.0, nsubs * 140.0)
