arguments.content:
import novamind_api as nm, json, math

def q(sql):
    try:
        return nm.query(sql).get('rows', [])
    except Exception as e:
        print('QUERY ERROR', e, sql)
        return []

day=int(nm.vars.current_day)
print('DAY', day)
try:
    print('COST_INFO', json.dumps(nm.infrastructure.get_cost_info(), indent=2))
except Exception as e: print('cost err',e)
try:
    print('MARKET_OVERVIEW', json.dumps(nm.market.get_market_overview(), indent=2)[:20000])
except Exception as e: print('overview err',e)
try:
    print('RESEARCH', json.dumps(nm.research.list_research_projects(), indent=2)[:20000])
except Exception as e: print('research err',e)

print('\nCONFIG overrides last 50')
for row in q('SELECT * FROM config_overrides ORDER BY id DESC LIMIT 50'): print(row)
print('\nCONFIG history last 20')
for row in q('SELECT * FROM config_history ORDER BY day DESC LIMIT 20'): print(row)

print('\nLEDGER cash and daily recent')
for row in q('SELECT SUM(amount) as cash FROM ledger'): print(row)
for row in q(f"SELECT day, SUM(amount) net, SUM(CASE WHEN amount>0 THEN amount ELSE 0 END) inflow, SUM(CASE WHEN amount<0 THEN amount ELSE 0 END) outflow FROM ledger WHERE day>={day-35} GROUP BY day ORDER BY day DESC"):
    print(row)
print('\nLEDGER by category recent windows')
for label, start in [('week',day-6),('14d',day-13),('28d',day-27),('all',0)]:
    print('WINDOW',label,start,day)
    for row in q(f"SELECT category, SUM(amount) amt, COUNT(*) n FROM ledger WHERE day BETWEEN {start} AND {day} GROUP BY category ORDER BY amt"):
        print(row)

print('\nSUBSCRIBERS active by group plan price')
for row in q("SELECT c.group_id, s.plan, ROUND(s.effective_price,2) ep, ROUND(s.listed_price,2) lp, ROUND(s.promotion,2) promo, COUNT(*) n, SUM(s.seat_count) seats, MIN(s.start_day) min_start, MAX(s.start_day) max_start, AVG(s.months_subscribed) avg_months FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id, s.plan, ROUND(s.effective_price,2), ROUND(s.listed_price,2), ROUND(s.promotion,2) ORDER BY c.group_id, s.plan, ep"):
    print(row)
print('\nSTATUS counts by group')
for row in q("SELECT c.group_id, s.status, COUNT(*) n, SUM(s.seat_count) seats FROM subscriptions s JOIN customers c USING(customer_id) GROUP BY c.group_id,s.status ORDER BY c.group_id,s.status"):
    print(row)
print('\nACQ created by day group status source recent')
for row in q(f"SELECT c.created_day, c.group_id, s.status, c.acquisition_source, COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.created_day>={day-14} GROUP BY c.created_day,c.group_id,s.status,c.acquisition_source ORDER BY c.created_day DESC,c.group_id,s.status,c.acquisition_source"):
    print(row)
print('\nDaily starts/recent statuses all sources')
for row in q(f"SELECT c.created_day, COUNT(*) leads, SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active_or_sub, SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) cancelled, SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost FROM customers c LEFT JOIN subscriptions s USING(customer_id) WHERE c.customer_type='individual' AND c.created_day>={day-28} GROUP BY c.created_day ORDER BY c.created_day DESC"):
    print(row)

print('\nCHURN/cancels by cancel/end day recent')
for row in q(f"SELECT s.end_day, c.group_id, s.plan, COUNT(*) n, SUM(s.seat_count) seats, AVG(s.months_subscribed) avg_months, AVG(s.effective_price) avg_ep FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='cancelled' AND s.end_day>={day-14} GROUP BY s.end_day,c.group_id,s.plan ORDER BY s.end_day DESC,c.group_id,s.plan"):
    print(row)

print('\nRENEWAL cohorts next 60d active by days_until/group/plan')
for row in q(f"SELECT (((billing_day_mod30 - {day}) % 30 + 30) % 30) AS days_until_bill, c.group_id, s.plan, COUNT(*) n, SUM(s.seat_count) seats, SUM(s.effective_price*s.seat_count) monthly_revenue, AVG(s.months_subscribed) avg_months FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY days_until_bill,c.group_id,s.plan ORDER BY days_until_bill,c.group_id,s.plan LIMIT 200"):
    print(row)
print('\nRENEWAL aggregate by days_until')
for row in q(f"SELECT (((billing_day_mod30 - {day}) % 30 + 30) % 30) AS days_until_bill, COUNT(*) n, SUM(s.seat_count) seats, SUM(s.effective_price*s.seat_count) monthly_revenue FROM subscriptions s WHERE s.status='subscribed' GROUP BY days_until_bill ORDER BY days_until_bill"):
    print(row)

print('\nAD recent daily')
for row in q(f"SELECT day, channel_id, group_id, SUM(spend) spend, SUM(leads_generated) leads, CASE WHEN SUM(leads_generated)>0 THEN SUM(spend)/SUM(leads_generated) END cpl FROM ad_channel_leads WHERE day>={day-21} GROUP BY day,channel_id,group_id ORDER BY day DESC,channel_id,group_id"):
    print(row)
print('\nAD aggregate by week/channel/group')
for row in q("SELECT CAST(day/7 AS INT) wk, MIN(day) d0, MAX(day) d1, channel_id, group_id, SUM(spend) spend, SUM(leads_generated) leads, CASE WHEN SUM(leads_generated)>0 THEN SUM(spend)/SUM(leads_generated) END cpl FROM ad_channel_leads GROUP BY wk,channel_id,group_id ORDER BY wk DESC,cpl"):
    print(row)

print('\nSERVICE recent')
for row in q(f"SELECT * FROM service_day WHERE day>={day-21} ORDER BY day DESC"):
    print(row)
print('\nUSAGE by group recent')
for row in q(f"SELECT du.day, c.group_id, COUNT(DISTINCT du.customer_id) users, SUM(du.usage_units) usage, AVG(du.usage_units) avg_usage FROM daily_usage du JOIN customers c USING(customer_id) WHERE du.day>={day-14} GROUP BY du.day,c.group_id ORDER BY du.day DESC,c.group_id"):
    print(row)

print('\nISSUES open by group/age')
for row in q("SELECT group_id, days_open, COUNT(*) n FROM issues WHERE status='open' GROUP BY group_id,days_open ORDER BY group_id,days_open DESC"):
