print('\nISSUES open summary')
for row in q("SELECT group_id, COUNT(*) open, SUM(CASE WHEN days_open>=2 THEN 1 ELSE 0 END) ge2, SUM(CASE WHEN days_open>=3 THEN 1 ELSE 0 END) ge3, MAX(days_open) max_age, AVG(days_open) avg_age FROM issues WHERE status='open' GROUP BY group_id ORDER BY group_id"):
