print('\nISSUES opened/resolved by open week/group')
for row in q("SELECT CAST(open_day/7 AS INT) wk, MIN(open_day) d0, MAX(open_day) d1, group_id, COUNT(*) opened, SUM(CASE WHEN status='resolved' THEN 1 ELSE 0 END) resolved_sofar, AVG(CASE WHEN status='resolved' THEN resolved_day-open_day END) avg_res_days FROM issues GROUP BY wk,group_id ORDER BY wk DESC,group_id"):
    print(row)
print('\nISSUES resolved recent')
for row in q(f"SELECT resolved_day, group_id, COUNT(*) n, AVG(days_open) avg_days_open, MAX(days_open) max_days_open FROM issues WHERE status='resolved' AND resolved_day>={day-14} GROUP BY resolved_day,group_id ORDER BY resolved_day DESC,group_id"):
    print(row)

print('\nSOCIAL recent')
