arguments.content:
import novamind_api as nm, json, math

def q(sql):
    try:
        return nm.query(sql).get('rows', [])
    except Exception as e:
        print('QUERY ERROR', e, sql)
        return []

day=int(nm.vars.current_day)
print('DAY', day)
print('cash', q('SELECT SUM(amount) cash FROM ledger'))
print('\nCOST_INFO')
try: print(json.dumps(nm.infrastructure.get_cost_info(), indent=2))
except Exception as e: print('err',e)
print('\nMARKET OVERVIEW small')
try:
    ov=nm.market.get_market_overview()
    print(json.dumps(ov, indent=2)[:12000])
except Exception as e: print('err',e)
print('\nRESEARCH')
try: print(json.dumps(nm.research.list_research_projects(), indent=2)[:12000])
except Exception as e: print('err',e)
print('\nCONFIG latest history/overrides')
for r in q('SELECT * FROM config_history ORDER BY day DESC LIMIT 8'): print(r)
for r in q('SELECT * FROM config_overrides ORDER BY id DESC LIMIT 20'): print(r)
print('\nLEDGER DAILY recent')
for r in q(f"SELECT day, SUM(amount) net, SUM(CASE WHEN amount>0 THEN amount ELSE 0 END) inflow, SUM(CASE WHEN amount<0 THEN amount ELSE 0 END) outflow FROM ledger WHERE day>={day-20} GROUP BY day ORDER BY day DESC"): print(r)
print('\nLEDGER category week/4wk')
for label,start in [('7d',day-6),('14d',day-13),('28d',day-27),('all',0)]:
    print('WINDOW',label,start,day)
    for r in q(f"SELECT category, SUM(amount) amt, COUNT(*) n FROM ledger WHERE day BETWEEN {start} AND {day} GROUP BY category ORDER BY amt"): print(r)
print('\nACTIVE subscribers by group plan price')
for r in q("SELECT c.group_id, s.plan, ROUND(s.effective_price,2) ep, ROUND(s.listed_price,2) lp, ROUND(s.promotion,2) promo, COUNT(*) n, SUM(s.seat_count) seats, MIN(s.start_day) min_start, MAX(s.start_day) max_start, AVG(? - s.start_day) avg_age FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id,s.plan,ROUND(s.effective_price,2),ROUND(s.listed_price,2),ROUND(s.promotion,2) ORDER BY c.group_id,s.plan,ep".replace('?', str(day))): print(r)
print('\nSTATUS by group')
for r in q("SELECT c.group_id, s.status, COUNT(*) n, SUM(s.seat_count) seats FROM subscriptions s JOIN customers c USING(customer_id) GROUP BY c.group_id,s.status ORDER BY c.group_id,s.status"): print(r)
print('\nRecent created by source daily')
for r in q(f"SELECT c.created_day, c.group_id, s.status, c.acquisition_source, COUNT(*) n FROM customers c LEFT JOIN subscriptions s USING(customer_id) WHERE c.customer_type='small' AND c.created_day>={day-14} GROUP BY c.created_day,c.group_id,s.status,c.acquisition_source ORDER BY c.created_day DESC,c.group_id,s.status,c.acquisition_source"): print(r)
print('\nRecent daily leads/sub/lost/cancel')
for r in q(f"SELECT c.created_day, COUNT(*) leads, SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) subscribed_now, SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost, SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) cancelled FROM customers c LEFT JOIN subscriptions s USING(customer_id) WHERE c.customer_type='small' AND c.created_day>={day-28} GROUP BY c.created_day ORDER BY c.created_day DESC"): print(r)
print('\nCancels recent by day group plan start_age')
for r in q(f"SELECT s.end_day, c.group_id, s.plan, ROUND(s.effective_price,2) ep, COUNT(*) n, AVG({day}-s.start_day) avg_age_now, AVG(s.end_day-s.start_day) avg_age_at_cancel FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='cancelled' AND s.end_day>={day-14} GROUP BY s.end_day,c.group_id,s.plan,ROUND(s.effective_price,2) ORDER BY s.end_day DESC,c.group_id,s.plan,ep"): print(r)
print('\nRenewal aggregate next 30 days current active')
for r in q(f"SELECT (((billing_day_mod30 - {day}) % 30 + 30) % 30) days_until_bill, COUNT(*) n, SUM(seat_count) seats, SUM(effective_price*seat_count) monthly_revenue FROM subscriptions WHERE status='subscribed' GROUP BY days_until_bill ORDER BY days_until_bill"): print(r)
print('\nRenewal weekly buckets')
for r in q(f"SELECT CASE WHEN (((billing_day_mod30 - {day}) % 30 + 30) % 30)=0 THEN 'd0' WHEN (((billing_day_mod30 - {day}) % 30 + 30) % 30) BETWEEN 1 AND 7 THEN 'd1_7' WHEN (((billing_day_mod30 - {day}) % 30 + 30) % 30) BETWEEN 8 AND 14 THEN 'd8_14' WHEN (((billing_day_mod30 - {day}) % 30 + 30) % 30) BETWEEN 15 AND 21 THEN 'd15_21' ELSE 'd22_29' END bucket, COUNT(*) n, SUM(seat_count) seats, SUM(effective_price*seat_count) monthly_revenue FROM subscriptions WHERE status='subscribed' GROUP BY bucket ORDER BY MIN((((billing_day_mod30 - {day}) % 30 + 30) % 30))"): print(r)
print('\nAD recent aggregate')
for r in q(f"SELECT day, channel_id, group_id, SUM(spend) spend, SUM(leads_generated) leads, CASE WHEN SUM(leads_generated)>0 THEN SUM(spend)/SUM(leads_generated) END cpl FROM ad_channel_leads WHERE day>={day-14} GROUP BY day,channel_id,group_id ORDER BY day DESC,channel_id,group_id"): print(r)
print('\nAD weekly aggregate')
for r in q("SELECT CAST(day/7 AS INT) wk, MIN(day) d0, MAX(day) d1, channel_id, group_id, SUM(spend) spend, SUM(leads_generated) leads, CASE WHEN SUM(leads_generated)>0 THEN SUM(spend)/SUM(leads_generated) END cpl FROM ad_channel_leads GROUP BY wk,channel_id,group_id ORDER BY wk DESC,channel_id,group_id"): print(r)
print('\nSERVICE recent')
for r in q(f"SELECT * FROM service_day WHERE day>={day-14} ORDER BY day DESC"): print(r)
print('\nUSAGE recent group avg')
for r in q(f"SELECT du.day, c.group_id, COUNT(DISTINCT du.customer_id) users, SUM(du.usage_units) usage, AVG(du.usage_units) avg_usage FROM daily_usage du JOIN customers c USING(customer_id) WHERE du.day>={day-7} GROUP BY du.day,c.group_id ORDER BY du.day DESC,c.group_id"): print(r)
print('\nISSUES open summary')
for r in q("SELECT group_id, COUNT(*) open, SUM(CASE WHEN days_open>=1 THEN 1 ELSE 0 END) ge1, SUM(CASE WHEN days_open>=2 THEN 1 ELSE 0 END) ge2, SUM(CASE WHEN days_open>=3 THEN 1 ELSE 0 END) ge3, MAX(days_open) max_age, AVG(days_open) avg_age FROM issues WHERE status='open' GROUP BY group_id ORDER BY group_id"): print(r)
print('\nISSUES open by age')
for r in q("SELECT group_id, days_open, COUNT(*) n FROM issues WHERE status='open' GROUP BY group_id,days_open ORDER BY group_id,days_open DESC"): print(r)
print('\nISSUES open/resolved recent daily')
