./novamind-operation python-c "import novamind_api as nm; DAY=nm.vars.current_day; 
for sql in [\"SELECT COUNT(*) open FROM issues WHERE status='open'\", \"SELECT COUNT(*) open FROM issues i JOIN customers c ON c.customer_id=i.customer_id JOIN subscriptions s ON s.customer_id=c.customer_id WHERE i.status='open' AND s.status='subscribed'\", \"SELECT COUNT(*) open FROM issues i JOIN customers c ON c.customer_id=i.customer_id LEFT JOIN subscriptions s ON s.customer_id=c.customer_id WHERE i.status='open' AND (s.status='subscribed' OR s.status IS NULL)\"]:
 print(sql, nm.query(sql)['rows'])"

