# NovaMind daily autopilot: runs inside simulator to handle time-sensitive tasks.
# Registered version is snapshotted; update/re-register when changing.
import json
import novamind_api as nm


def safe_query(sql):
    try:
        return nm.query(sql).get('rows', [])
    except Exception:
        return []


def autoscale_capacity():
    # Registered scripts appear to run at week boundaries, not every simulated day.  Use
    # enough headroom for a full week of ad-driven growth, not just yesterday's load.
    caps = [50000, 200000, 800000, 2500000, 8000000, 25000000, 80000000, 300000000]
    day = int(nm.vars.current_day)
    rows = safe_query(f"SELECT MAX(total_usage_units) AS u FROM service_day WHERE day >= {max(0, day-7)}")
    usage = 0.0
    if rows and rows[0].get('u') is not None:
        usage = float(rows[0]['u'] or 0)
    subs = safe_query("SELECT COUNT(*) AS n FROM subscriptions WHERE status='subscribed'")
    nsubs = int(subs[0]['n']) if subs else 0
    # Budget for one week of growth without jumping to the next tier too early.
    # Actual S1 usage has averaged ~75-85 units/day/sub (peak days near ~85),
    # so avoid an overly conservative jump from tier5 to tier6 based only on
    # subscriber count. Use recent measured peak with headroom plus a 95
    # units/sub guardrail; this keeps tier5 until usage is genuinely near 25M.
    if nsubs > 20000:
        need = max(usage * 1.75, nsubs * 95.0, 800001.0)
    elif nsubs > 6000:
        need = max(usage * 2.0, nsubs * 140.0, 800001.0)
    elif nsubs > 500:
        need = max(usage * 2.0, nsubs * 140.0)
    else:
        need = max(usage * 1.5, nsubs * 160.0)
    target = 0
    for i, cap in enumerate(caps):
        if cap >= need:
            target = i
            break
    try:
        nm.infrastructure.set_capacity_tier(tier=target)
    except Exception:
        pass


def latest_enterprise_customer_messages():
    # One active enterprise thread per customer. Reply only when the latest open turn is from customer.
    sql = """
    SELECT et.message_id, et.customer_id, et.thread_type, et.turn_number, et.day, et.seat_count,
           c.group_id, c.customer_type
    FROM enterprise_turns et
    JOIN (
      SELECT customer_id, MAX(message_id) AS mid
      FROM enterprise_turns
      WHERE closed=0
      GROUP BY customer_id
    ) latest ON et.message_id = latest.mid
    JOIN customers c ON c.customer_id = et.customer_id
    WHERE et.sender='customer'
    ORDER BY et.day ASC, et.message_id ASC
    """
    return safe_query(sql)


def group_offers(group_id, thread_type):
    # Month-to-month only. Prices are per seat. Offer cheaper rescue pricing for churn risk.
    base = {
        'E1': [('A', 8.0), ('B', 12.0), ('C', 16.0)],
        'E2': [('A', 40.0), ('B', 70.0), ('C', 90.0)],
        'E3': [('A', 50.0), ('B', 85.0), ('C', 110.0)],
    }
    # Sensible defaults for discovered enterprise groups until manually tuned.
    if group_id not in base:
        if str(group_id).startswith('D_E'):
            offers = [('A', 35.0), ('B', 65.0), ('C', 95.0)]
        else:
            offers = [('A', 19.0), ('B', 79.0), ('C', 149.0)]
    else:
        offers = base[group_id]
    if thread_type in ('churn_prevention', 'renewal'):
        offers = [(p, round(price * 0.85, 2)) for p, price in offers]
    return [[p, price] for p, price in offers]


def answer_enterprise_threads():
    rows = latest_enterprise_customer_messages()
    if not rows:
        return
    deals = []
    for r in rows:
        cid = int(r['customer_id'])
        gid = r.get('group_id') or ''
        ttype = r.get('thread_type') or 'new_lead'
        deals.append([cid, group_offers(gid, ttype)])
    if deals:
        try:
            nm.enterprise.send_enterprise_deal(deals=deals)
        except Exception:
            # If a batch fails because one row is stale, retry individually.
            for d in deals:
                try:
                    nm.enterprise.send_enterprise_deal(deals=[d])
                except Exception:
                    pass


def main():
    autoscale_capacity()
    answer_enterprise_threads()

main()
