./novamind-operation python-c "import novamind_api as nm, json; day=nm.vars.current_day; queries=[('raw open by group age',f'''SELECT group_id, COUNT(*) n, SUM(CASE WHEN days_open>=2 THEN 1 ELSE 0 END) age2, SUM(CASE WHEN days_open>=5 THEN 1 ELSE 0 END) age5, MAX(days_open) max_age, AVG(days_open) avg_age FROM issues WHERE status='open' GROUP BY group_id ORDER BY n DESC'''),('raw open age histogram', '''SELECT days_open, COUNT(*) n FROM issues WHERE status='open' GROUP BY days_open ORDER BY days_open'''),('open cancelled vs active?', '''SELECT s.status sub_status, COUNT(*) n, SUM(CASE WHEN i.days_open>=2 THEN 1 ELSE 0 END) age2, MAX(i.days_open) max_age FROM issues i LEFT JOIN subscriptions s ON s.customer_id=i.customer_id WHERE i.status='open' GROUP BY s.status''')];
for title,sql in queries:
 print('\n##',title);
 for r in nm.query(sql)['rows']: print(r)
"

