./novamind-operation python-c "import novamind_api as nm; 
for g in ['S2','S3']:
 print('\n##', g, 'all leads by created_day/source/status counts');
 rows=nm.query(f'''SELECT c.created_day, c.acquisition_source, COUNT(*) leads, SUM(CASE WHEN s.status IN ('subscribed','cancelled') THEN 1 ELSE 0 END) ever, SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost, SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active, SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) canc FROM customers c LEFT JOIN subscriptions s ON s.customer_id=c.customer_id WHERE c.group_id='{g}' AND c.customer_type='small' GROUP BY c.created_day,c.acquisition_source HAVING leads>0 ORDER BY c.created_day LIMIT 200''')['rows'];
 for r in rows[-80:]: print(r)
" > s2s3_history.txt && sed -n '1,240p' s2s3_history.txt

