arguments.command:
./novamind-operation python-c "import novamind_api as nm; day=nm.vars.current_day; rows=nm.query(f'''SELECT c.group_id, s.plan, COUNT(DISTINCT du.customer_id) users, SUM(du.usage_units) usage, ROUND(AVG(du.usage_units),1) avg_daily_user_usage FROM daily_usage du JOIN customers c ON c.customer_id=du.customer_id JOIN subscriptions s ON s.customer_id=du.customer_id WHERE du.day BETWEEN {day-6} AND {day} AND s.status='subscribed' GROUP BY c.group_id,s.plan ORDER BY usage DESC''')['rows'];
for r in rows: print(r)
"

