rows=nm.query('SELECT settings_json FROM config_overrides WHERE setting_type=\'promotion\' ORDER BY id DESC LIMIT 1')['rows']
settings=json.loads(rows[0]['settings_json']); by=settings['by_customer']; print('n by_customer', len(by));
# create temp? cannot use by_customer in SQL directly, query all d139-d145 statuses with promotion values
for r in nm.query('''SELECT s.start_day, s.plan, s.status, s.promotion, COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id=\'S1\' AND s.start_day BETWEEN 139 AND 145 AND s.status IN (\'subscribed\',\'cancelled\') GROUP BY 1,2,3,4 ORDER BY 1,2,3,4''')['rows']: print(r)
# count current by_customer IDs by start/status/plan by paginating not needed 17k: construct temp impossible; use Python batches
ids=list(map(int, by.keys()))
from collections import Counter,defaultdict
ctr=Counter(); batches=[ids[i:i+900] for i in range(0,len(ids),900)]
for b in batches:
    inlist=','.join(map(str,b))
    for r in nm.query(f'''SELECT s.start_day, s.plan, s.status, COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.customer_id IN ({inlist}) GROUP BY 1,2,3''')['rows']:
        ctr[(r['start_day'],r['plan'],r['status'])]+=r['n']
print('promo ids by start/plan/status')
for k,v in sorted(ctr.items()): print(k,v)
