import novamind_api as nm, math, copy
DAY=int(nm.vars.current_day)
q=lambda sql:nm.query(sql)['rows']
cash=float(q('SELECT SUM(amount) cash FROM ledger')[0]['cash'])
# active cohorts
rows=q('''SELECT c.group_id,s.start_day,s.plan,COUNT(*) n, AVG(s.listed_price) price
FROM subscriptions s JOIN customers c USING(customer_id)
WHERE s.status='subscribed' AND c.customer_type='small'
GROUP BY 1,2,3''')
coh={(r['group_id'],int(r['start_day']),r['plan']): {'n':float(r['n']),'price':float(r['price'])} for r in rows}
obs=q(f'''SELECT c.group_id,c.acquisition_source,s.status,s.plan,COUNT(*) n
FROM customers c JOIN subscriptions s USING(customer_id)
WHERE c.customer_type='small' AND c.created_day BETWEEN {DAY-6} AND {DAY}
GROUP BY 1,2,3,4''')
s1_paid=sum(r['n'] for r in obs if r['group_id']=='S1' and r['acquisition_source']=='content_marketing' and r['status']=='subscribed')
s1_net=sum(r['n'] for r in obs if r['group_id']=='S1' and r['acquisition_source']=='network' and r['status']=='subscribed')
# Use all S2/S3 lead/sub observation for conversion/plan mix; paid raw leads is action-based below.
oth_leads_obs=sum(r['n'] for r in obs if r['group_id'] in ('S2','S3'))
oth_subs_obs=sum(r['n'] for r in obs if r['group_id'] in ('S2','S3') and r['status']=='subscribed')
s1_mix={p:sum(r['n'] for r in obs if r['group_id']=='S1' and r['status']=='subscribed' and r['plan']==p) for p in ['A','B','C']}
s1_new=sum(s1_mix.values()) or 1
s1_frac={p:s1_mix[p]/s1_new for p in s1_mix}
oth_mix={p:sum(r['n'] for r in obs if r['group_id'] in ('S2','S3') and r['status']=='subscribed' and r['plan']==p) for p in ['A','B','C']}
oth_new=sum(oth_mix.values()) or 1
oth_frac={p:oth_mix[p]/oth_new for p in oth_mix}
tiercost={'A':0.0003,'B':0.006,'C':0.006}
usage=q(f'''SELECT c.group_id,s.plan,SUM(du.usage_units) usage
FROM daily_usage du JOIN subscriptions s USING(customer_id) JOIN customers c USING(customer_id)
WHERE du.day BETWEEN {DAY-6} AND {DAY} AND s.status='subscribed'
GROUP BY 1,2''')
compute_week=sum((r['usage'] or 0)*tiercost[r['plan']] for r in usage)
active=sum(v['n'] for v in coh.values())
compute_per_active_day=compute_week/(7*active)
print('inputs cash',round(cash),'active',round(active),'s1_paid',s1_paid,'s1_net',s1_net,'oth_leads_obs',oth_leads_obs,'oth_subs_obs',oth_subs_obs,'s1_frac',s1_frac,'oth_frac',oth_frac,'compute_week',round(compute_week),'cpad',round(compute_per_active_day,4))
prices={'A':19.0,'B':79.0,'C':149.0}
def add_new(coh, day, group, n, frac):
    for p,f in frac.items():
        if n*f>0:
            key=(group,day,p)
            if key not in coh: coh[key]={'n':0.0,'price':prices[p]}
            coh[key]['n']+=n*f

def init_rev_s1(frac): return frac['A']*14 + frac['B']*74 + frac['C']*144  # $5 lead promo

def init_rev_oth(frac): return frac['A']*0 + frac['B']*59 + frac['C']*129  # $20 lead promo, A floors at 0? A 19-20=0

def simulate(label, params, H=182):
    c=cash; cohorts=copy.deepcopy(coh); out={}
    paid_base=s1_paid/7
    net_per_active=s1_net/7/active
    # observed organic S2/S3 network leads per active, excluding paid content/search raw leads (paid raw action modeled separately)
    oth_network_leads=sum(r['n'] for r in obs if r['group_id'] in ('S2','S3') and r['acquisition_source']=='network')
    oth_net_per_active=oth_network_leads/7/active
    fixed_daily=28000+params.get('ops_daily',29000)+params.get('dev_daily',36000)+params.get('ads_daily',16000)
    for t in range(DAY+1, DAY+H+1):
        d=t-DAY
        act=sum(v['n'] for v in cohorts.values())
        # S1 slows with saturation but T3/T5/T6 support conversion/reputation.
        sat=max(params.get('sat_floor',0.30), 1-params.get('sat_decline_84',0.25)*(d/84))
        if d>84: sat=max(params.get('sat_floor_post',0.22), sat-params.get('sat_decline_post',0.0015)*(d-84))
        s1_paid_today=paid_base*sat*params.get('s1_paid_mult',1.0)
        s1_net_today=net_per_active*act*sat*params.get('s1_net_mult',1.0)
        s1_conv=params.get('s1_conv',0.975)
        if t>=191: s1_conv=min(1.0,s1_conv+0.010)
        if t>=198: s1_conv=min(1.0,s1_conv+0.004)
        if t>=231: s1_conv=min(1.0,s1_conv+0.004)
        s1_new=(s1_paid_today+s1_net_today)*s1_conv
        c += s1_new*init_rev_s1(s1_frac); add_new(cohorts,t,'S1',s1_new,s1_frac)
        # S2/S3: paid content was scaled to S2 $4k/d and S3 $2k/d; base assumes partial saturation from last observed CPL.
        oth_org_leads=oth_net_per_active*act*params.get('oth_org_mult',1.0)
        oth_paid_leads=params.get('oth_paid_leads_day',600.0)  # raw paid leads/day after scaling
        conv=params.get('oth_conv0',0.26)
        # targeted dev + R&D ramps conversion
        if t>=191: conv=params.get('oth_conv_t3',0.34)
        if t>=198: conv=params.get('oth_conv_t5',0.42)
        if t>=231: conv=params.get('oth_conv_t6',0.58)
        if t>=268: conv=min(params.get('oth_conv_cap',0.75),conv+0.03)
        conv=min(params.get('oth_conv_cap',0.75),conv*params.get('oth_conv_mult',1.0))
        oth_new=(oth_org_leads+oth_paid_leads)*conv
        c += oth_new*init_rev_oth(oth_frac); add_new(cohorts,t,'S2S3',oth_new,oth_frac)
        leads=s1_paid_today+s1_net_today+oth_org_leads+oth_paid_leads
        compute=compute_per_active_day*act*(1+params.get('usage_growth',0.035)*d/84)
        # heavier S2/S3 mix gradually raises per-active compute beyond simple active growth
        compute*=1+params.get('mix_compute_growth',0.08)*min(d,84)/84
        c -= compute + fixed_daily + 0.5*leads
        # billing/churn; current policy: $8 S1 p30 rescue for start 160-166 only; future weeks rotate similarly for <=175, $5 for >=176.
        for key,v in list(cohorts.items()):
            g,sd,p=key
            if sd==t or v['n']<=0: continue
            if sd%30==t%30:
                age=t-sd
                if g=='S1':
                    if age<45:
                        disc=8.0 if 160<=sd<=175 else (5.0 if sd>=176 else 0.0)
                        basep=params.get('s1_p30_A',0.105) if p=='A' else params.get('s1_p30_B',0.10)
                    elif age<75:
                        disc=0.0
                        basep=params.get('s1_p60_A',0.13) if p=='A' else params.get('s1_p60_B',0.055)
                    else:
                        disc=0.0
                        basep=params.get('s1_p90_A',0.035) if p=='A' else params.get('s1_p90_B',0.025)
                    if t>=191: basep*=params.get('t3_churn_mult',0.88)
                    if t>=198: basep*=params.get('t5_churn_mult',0.93)
                    if t>=231: basep*=params.get('t6_churn_mult',0.78)
                else:
                    disc=0.0
                    basep=params.get('oth_p30',0.10) if age<45 else params.get('oth_p60',0.06)
                    if t>=198: basep*=0.88
                    if t>=231: basep*=0.72
                basep=max(0.004,min(0.38,basep*params.get('churn_mult',1.0)))
                pay=v['n']*(1-basep); v['n']=pay
                c += pay*max(prices[p]-disc,0)
        # future R&D costs under likely policy; thresholds are cash-before-start.
        for name,day,cost,thresh in params.get('rnd_schedule',[]):
            flag='started_'+name
            if t>=day and not params.get(flag,False) and c>thresh:
                c-=cost; params[flag]=True
        out[d]=c
    print(label, {h: round(out[h]) for h in [7,28,84,182]})
    return out
base={'rnd_schedule':[('t7',222,1166667,5800000),('t8',245,1333333,9000000),('t9',285,1500000,14000000),('t10',325,1666667,22000000)]}
low=base.copy(); low.update({'s1_paid_mult':0.78,'s1_net_mult':0.75,'s1_conv':0.95,'sat_decline_84':0.48,'sat_floor':0.16,'sat_floor_post':0.12,'oth_paid_leads_day':350,'oth_conv_mult':0.65,'s1_p30_A':0.16,'s1_p30_B':0.16,'s1_p60_A':0.22,'s1_p90_A':0.06,'churn_mult':1.25,'usage_growth':0.06,'mix_compute_growth':0.14,'rnd_schedule':[('t7',250,1166667,9000000),('t8',305,1333333,15000000)]})
high=base.copy(); high.update({'s1_paid_mult':1.12,'s1_net_mult':1.16,'s1_conv':0.99,'sat_decline_84':0.12,'sat_floor':0.45,'sat_floor_post':0.38,'oth_paid_leads_day':850,'oth_conv_mult':1.25,'oth_conv_cap':0.90,'s1_p30_A':0.055,'s1_p30_B':0.055,'s1_p60_A':0.08,'s1_p60_B':0.035,'s1_p90_A':0.02,'churn_mult':0.75,'usage_growth':0.025,'mix_compute_growth':0.05,'rnd_schedule':[('t7',215,1166667,5000000),('t8',235,1333333,7500000),('t9',260,1500000,11000000),('t10',295,1666667,17000000),('t11',345,2500000,30000000)]})
for label,p in [('low',low),('base',base.copy()),('high',high)]: simulate(label,p)

