import novamind_api as nm, json
print('day', nm.vars.current_day)
results=[]
for i in range(5):
    try:
        res=nm.market.research_market()
        print('attempt', i+1, json.dumps(res, indent=2))
        results.append(res)
    except Exception as e:
        print('attempt', i+1, 'ERROR', type(e).__name__, str(e))
print('overview')
print(json.dumps(nm.market.get_market_overview(), indent=2))
for gid in [g['group_id'] for g in nm.market.get_market_overview().get('known_groups',[]) if g['group_id'].startswith('D_')]:
    try:
        print('insights', gid, json.dumps(nm.market.get_group_insights(group_id=gid), indent=2)[:4000])
    except Exception as e: print('insights err', gid, e)
print('cash', nm.query('SELECT ROUND(SUM(amount),2) cash FROM ledger')['rows'][0])

