import novamind_api as nm, math, copy, statistics
DAY=int(nm.vars.current_day)
q=lambda sql:nm.query(sql)['rows']
cash=float(q('SELECT SUM(amount) cash FROM ledger')[0]['cash'])
print('cash',cash,'day',DAY)
# Active cohorts by group, start_day, plan
rows=q('''SELECT c.group_id,s.start_day,s.plan,COUNT(*) n, AVG(s.listed_price) price
FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id
WHERE s.status='subscribed' AND c.customer_type='small'
GROUP BY c.group_id,s.start_day,s.plan''')
base_coh={(r['group_id'],int(r['start_day']),r['plan']): float(r['n']) for r in rows}
# Last week observed acquisition and ad leads
START=DAY-6
obs=q(f'''SELECT c.group_id,c.acquisition_source,s.status,s.plan,COUNT(*) n
FROM customers c JOIN subscriptions s ON c.customer_id=s.customer_id
WHERE c.customer_type='small' AND c.created_day BETWEEN {START} AND {DAY}
GROUP BY c.group_id,c.acquisition_source,s.status,s.plan''')
# Plan mix per group from last week new subscribers; defaults for new groups
def mix_for(g):
    d={p:sum(r['n'] for r in obs if r['group_id']==g and r['status']=='subscribed' and r['plan']==p) for p in ['A','B','C']}
    total=sum(d.values())
    if total==0:
        if g=='D_S07': return {'A':0.05,'B':0.90,'C':0.05}
        if g=='D_S10': return {'A':0.10,'B':0.80,'C':0.10}
        return {'A':0.2,'B':0.7,'C':0.1}
    return {p:d[p]/total for p in d}
planmix={g:mix_for(g) for g in ['S1','S2','S3','D_S07','D_S10']}
print('planmix',planmix)
# Active by group
active0={}
for (g,sd,p),n in base_coh.items(): active0[g]=active0.get(g,0)+n
print('active0',active0)
# Recent daily net leads/subs by group/source
for g in ['S1','S2','S3']:
    leads=sum(r['n'] for r in obs if r['group_id']==g)
    subs=sum(r['n'] for r in obs if r['group_id']==g and r['status']=='subscribed')
    print('obs',g,'leads',leads,'subs',subs,'conv',subs/leads if leads else None)
# Use current spend and last observed CPL to estimate paid leads/day.
# Last week paid content leads: S1 1190 @5k/d; S2 24877 @25k/d; S3 7309 @15k/d.
base_paid_day={'S1':1190/7*(5000/5000),'S2':24877/7*(35000/25000),'S3':7309/7*(25000/15000),'D_S07':5000/12.0} # assume CPL $12
base_org_day={'S1':5743/7,'S2':4289/7,'S3':4043/7,'D_S07':250,'D_S10':400}
conv0={'S1':0.978,'S2':0.982,'S3':0.84,'D_S07':0.78,'D_S10':0.0}
prices={'A':19.0,'B':79.0,'C':149.0}
leadpromo={'S1':5.0,'S2':20.0,'S3':30.0,'D_S07':20.0,'D_S10':30.0}
# compute costs per group/plan from recent usage; D groups estimates
cost_unit={'A':0.002,'B':0.006,'C':0.006}
usage_rows=q(f'''SELECT c.group_id,s.plan,SUM(du.usage_units) usage, COUNT(DISTINCT du.customer_id) users
FROM daily_usage du JOIN subscriptions s ON s.customer_id=du.customer_id JOIN customers c ON c.customer_id=du.customer_id
WHERE du.day BETWEEN {START} AND {DAY} AND s.status='subscribed'
GROUP BY c.group_id,s.plan''')
usage_per_day={}
for r in usage_rows:
    users=max(r['users'],1); usage_per_day[(r['group_id'],r['plan'])]=(r['usage']/7)/users
# defaults
for p in ['A','B','C']:
    usage_per_day[('D_S07',p)]={'A':140,'B':180,'C':220}[p]
    usage_per_day[('D_S10',p)]={'A':80,'B':90,'C':120}[p]
print('usage_per_day sample', {k:round(v,1) for k,v in usage_per_day.items() if k[0] in ['S2','S3','D_S07','D_S10']})

def add_new(coh,g,day,n):
    if n<=0: return
    mix=planmix[g]
    for p,f in mix.items():
        if f*n>0: coh[(g,day,p)]=coh.get((g,day,p),0)+f*n

def init_rev(g,n):
    mix=planmix[g]; promo=leadpromo.get(g,0)
    return n*sum(mix[p]*max(prices[p]-promo,0) for p in mix)

def simulate(label, mult, H=182):
    coh=copy.deepcopy(base_coh); c=cash; outs={}
    rnd_done=set()
    for t in range(DAY+1, DAY+H+1):
        d=t-DAY
        # current active by group before acquisition
        active={}
        for (g,sd,p),n in coh.items(): active[g]=active.get(g,0)+n
        # acquisition with saturation and future quality boosts
        new_total_leads=0
        for g in ['S1','S2','S3','D_S07','D_S10']:
            cap=mult.get('cap_'+g, {'S1':300000,'S2':180000,'S3':70000,'D_S07':60000,'D_S10':60000}[g])
            sat=max(0.05, 1-(active.get(g,0)/cap)**1.35) if cap>0 else 1
            if g=='S1': sat=max(0.15,sat) # replacement demand continues
            paid=base_paid_day.get(g,0)*mult.get('paid_'+g,1.0)
            org=base_org_day.get(g,0)*mult.get('org_'+g,1.0)*(1+0.25*active.get(g,0)/max(active0.get(g,1),1))
            # D_S10 quality gate: dev unlocks around d18; T6 d21, T10 d30 greatly help
            conv=conv0[g]*mult.get('conv_'+g,1.0)
            if g=='D_S10':
                if d<18: conv=0.0
                elif d<21: conv=0.35*mult.get('conv_D_S10',1.0)
                elif d<30: conv=0.65*mult.get('conv_D_S10',1.0)
                else: conv=0.85*mult.get('conv_D_S10',1.0)
                # likely add D_S10 ads after T6 if cash healthy; model modest paid leads
                if d>=21: paid+=mult.get('future_paid_D_S10',300)
                if d>=31: paid+=mult.get('future_paid_D_S10_post',400)
            if g in ['S2','S3','D_S07'] and d>=21: conv=min(0.995,conv*1.03)
            if g in ['S2','S3','D_S07','D_S10'] and d>=30: conv=min(0.995,conv*1.08)
            leads=(paid+org)*sat
            subs=leads*min(0.995,conv)
            new_total_leads+=leads
            c += init_rev(g,subs)
            add_new(coh,g,t,subs)
        # costs
        fixed=28000+70000+76000+84000
        # capacity tier7 when active/usage likely passes threshold
        if d>=14 or sum(active.values())>470000:
            fixed += (75000-28000)
        # compute from current cohorts
        compute=0
        for (g,sd,p),n in coh.items():
            up=usage_per_day.get((g,p), usage_per_day.get(('S2',p),150))
            compute += n*up*cost_unit[p]
        # usage inflation / heavier mix
        compute *= (1+mult.get('usage_infl',0.04)*d/84)
        c -= fixed + compute + 0.5*new_total_leads
        # bill renewals
        for key,n in list(coh.items()):
            g,sd,p=key
            if n<=0 or sd==t: continue
            if sd%30==t%30:
                age=t-sd
                promo=0.0; churn=0.04
                if g=='S1':
                    if age<45:
                        promo=12.0 if p=='A' else 8.0
                        churn=mult.get('s1_p30_A',0.09) if p=='A' else mult.get('s1_p30_B',0.07)
                    elif age<75:
                        promo=5.0
                        churn=mult.get('s1_p60',0.08)
                    else:
                        churn=mult.get('s1_p90',0.055)
                    if d>=30: churn*=0.45
                    elif d>=21: churn*=0.75
                elif g in ['S2','S3']:
                    churn=mult.get('s23_p30',0.035) if age<45 else mult.get('s23_p60',0.025)
                    if d>=21: churn*=0.75
                    if d>=30: churn*=0.55
                elif g=='D_S07':
                    churn=mult.get('ds07_p30',0.08) if age<45 else 0.05
                    if d>=30: churn*=0.60
                else:
                    churn=mult.get('ds10_p30',0.10) if age<45 else 0.06
                    if d>=30: churn*=0.60
                churn=max(0.002,min(0.35,churn*mult.get('churn_mult',1.0)))
                survivors=n*(1-churn)
                coh[key]=survivors
                c += survivors*max(prices[p]-promo,0)
        # future R&D spending policy (not yet committed but likely)
        for name,day,cost,threshold in mult.get('rnd',[]):
            if name not in rnd_done and t>=day and c>threshold:
                c-=cost; rnd_done.add(name)
        outs[d]=c
    print(label,{h:round(outs[h]) for h in [7,28,84,182]})
    return outs
