./novamind-operation python-c "import novamind_api as nm
for label,lo,hi in [('p30',188,194),('p60',158,164),('p90',128,134),('p120',98,104)]:
 print(label,lo,hi)
 r=nm.query(f'''SELECT s.start_day,s.plan,COUNT(*) active,ROUND(AVG(s.effective_price),2) eff,ROUND(AVG(COALESCE(s.promotion,0)),2) promo,ROUND(SUM(s.effective_price),2) eff_mrr FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.group_id=\'S1\' AND s.status=\'subscribed\' AND s.start_day BETWEEN {lo} AND {hi} GROUP BY s.start_day,s.plan ORDER BY s.start_day,s.plan''')
 for row in r['rows']: print(row)
" | sed -n '1,200p'

