import novamind_api as nm, copy, math
DAY=int(nm.vars.current_day)
q=lambda sql:nm.query(sql)['rows']
cash=float(q('SELECT SUM(amount) cash FROM ledger')[0]['cash'])
print('cash',round(cash,2),'day',DAY)
START=DAY-6
# cohorts
rows=q('''SELECT c.group_id,s.start_day,s.plan,COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' AND c.customer_type='small' GROUP BY c.group_id,s.start_day,s.plan''')
base={(r['group_id'],int(r['start_day']),r['plan']):float(r['n']) for r in rows}
active0={}
for (g,sd,p),n in base.items(): active0[g]=active0.get(g,0)+n
print('active0',active0)
# new sub plan mix observed last week
obs=q(f'''SELECT c.group_id,s.status,s.plan,COUNT(*) n FROM customers c JOIN subscriptions s ON c.customer_id=s.customer_id WHERE c.customer_type='small' AND c.created_day BETWEEN {START} AND {DAY} GROUP BY c.group_id,s.status,s.plan''')
def mix(g):
    d={p:sum(r['n'] for r in obs if r['group_id']==g and r['status']=='subscribed' and r['plan']==p) for p in ['A','B','C']}
    tot=sum(d.values())
    if tot==0:
        if g=='D_S07': return {'A':0.05,'B':0.90,'C':0.05}
        if g=='D_S10': return {'A':0.35,'B':0.60,'C':0.05}
        return {'A':0.2,'B':0.7,'C':0.1}
    return {p:d[p]/tot for p in d}
planmix={g:mix(g) for g in ['S1','S2','S3','D_S07','D_S10']}
print('planmix',planmix)
# observed paid leads/day by group from current old spend; planned spend scale
ad=q(f'''SELECT group_id,SUM(leads_generated) leads,SUM(spend) spend FROM ad_channel_leads WHERE day BETWEEN {START} AND {DAY} GROUP BY group_id''')
obs_paid={r['group_id']:r['leads']/7 for r in ad}
obs_spend={r['group_id']:r['spend']/7 for r in ad}
planned_spend={'S1':0,'S2':45000,'S3':30000,'D_S07':0,'D_S10':0}
paid_day={}
for g in ['S1','S2','S3','D_S07','D_S10']:
    if planned_spend.get(g,0)<=0: paid_day[g]=0.0
    elif g in obs_paid and obs_spend.get(g,0)>0:
        paid_day[g]=obs_paid[g]*(planned_spend[g]/obs_spend[g])**0.80
    else:
        paid_day[g]=planned_spend[g]/30.0
print('paid_day planned',paid_day,'obs_paid',obs_paid)
# observed organic/network leads per day
org_rows=q(f'''SELECT c.group_id,c.acquisition_source,COUNT(*) leads FROM customers c JOIN subscriptions s ON c.customer_id=s.customer_id WHERE c.customer_type='small' AND c.created_day BETWEEN {START} AND {DAY} AND c.acquisition_source='network' GROUP BY c.group_id,c.acquisition_source''')
org_day={r['group_id']:r['leads']/7 for r in org_rows}
for g in ['S1','S2','S3','D_S07','D_S10']: org_day.setdefault(g,0.0)
print('org_day',org_day)
# usage
cost_unit={'A':0.002,'B':0.006,'C':0.006}
usage_rows=q(f'''SELECT c.group_id,s.plan,SUM(du.usage_units) usage, COUNT(DISTINCT du.customer_id) users FROM daily_usage du JOIN subscriptions s ON s.customer_id=du.customer_id JOIN customers c ON c.customer_id=du.customer_id WHERE du.day BETWEEN {START} AND {DAY} AND s.status='subscribed' GROUP BY c.group_id,s.plan''')
usage={}
for r in usage_rows: usage[(r['group_id'],r['plan'])]=(r['usage']/7)/max(1,r['users'])
for p in ['A','B','C']:
    usage[('D_S07',p)]={'A':170,'B':207,'C':260}[p]
    usage[('D_S10',p)]={'A':105,'B':110,'C':160}[p]
print('usage sample',{k:round(v,1) for k,v in usage.items() if k[0] in ['S2','S3','D_S07','D_S10']})
prices={'A':19.0,'B':79.0,'C':149.0}

def add_new(coh,g,day,n):
    if n<=0: return
    for p,f in planmix[g].items():
        if f>0: coh[(g,day,p)]=coh.get((g,day,p),0)+n*f

def init_rev(g,n):
    # ledger has tracked near list/effective price; do not subtract lead promos in this empirical model
    return n*sum(planmix[g][p]*prices[p] for p in ['A','B','C'])

def simulate(name, pars, H=182):
    coh=copy.deepcopy(base); c=cash; outs={}; done=set()
    for t in range(DAY+1,DAY+H+1):
        d=t-DAY
        active={}
        for (g,sd,p),n in coh.items(): active[g]=active.get(g,0)+n
        # future weekly actions after prior dashboards, not included in exact dashboard day cash
        # Deduct planned R&D/market spending after day 224/231/238 etc by applying from the following day.
        for tag,action_day,cost,threshold in pars.get('future_spend',[]):
            if tag not in done and t>=action_day+1 and c>threshold:
                c-=cost; done.add(tag)
        new_leads=0
        # acquisition
        for g in ['S1','S2','S3','D_S07','D_S10']:
            cap=pars.get('cap_'+g, {'S1':300000,'S2':175000,'S3':70000,'D_S07':75000,'D_S10':50000}[g])
            rawsat=max(0.04,1-(active.get(g,0)/cap)**1.25) if cap>0 else 1
            cur=max(0.04,1-(active0.get(g,0)/cap)**1.25) if active0.get(g,0)>0 else 1
            sat=rawsat/cur
            if g=='S1': sat=max(0.30,sat)
            paid=paid_day.get(g,0)*pars.get('paid_mult_'+g,1.0)
            # likely future D group ad tests after quality/R&D unlocks
            if g=='D_S10' and d>=8: paid += pars.get('future_paid_D_S10_preT6',250)
            if g=='D_S10' and d>=15: paid += pars.get('future_paid_D_S10_postT6',350)
            if g=='D_S10' and d>=24: paid += pars.get('future_paid_D_S10_postT10',600)
            if g=='D_S07' and d>=15: paid += pars.get('future_paid_D_S07_postT6',250)
            if g=='D_S07' and d>=24: paid += pars.get('future_paid_D_S07_postT10',550)
            # organic scales with related installed base but slower than linear
            org=org_day.get(g,0)*pars.get('org_mult_'+g,1.0)*(0.65+0.35*sum(active.values())/max(1,sum(active0.values())))
            conv={'S1':0.965,'S2':0.993,'S3':0.875,'D_S07':0.0,'D_S10':0.15}[g]
            if g=='D_S07':
                if d<6: conv=0.0
                elif d<15: conv=0.10
                elif d<24: conv=0.55
                else: conv=0.86
            if g=='D_S10':
                if d<3: conv=0.08
                elif d<8: conv=0.35
                elif d<15: conv=0.62
                elif d<24: conv=0.82
                else: conv=0.90
            conv*=pars.get('conv_mult_'+g,1.0)
            conv=max(0,min(0.995,conv))
            leads=(paid+org)*sat
            subs=leads*conv
            new_leads+=leads
            c+=init_rev(g,subs)
            add_new(coh,g,t,subs)
        # costs: fixed daily settings and likely future scaling
        cap_cost=28000 if (d<=7 and sum(active.values())<470000) else 75000
        ads=75000
        if d>=8: ads+=pars.get('future_ads_extra_after224',10000)
        if d>=15: ads+=pars.get('future_ads_extra_after231',10000)
        ops=80000 if d<30 else 90000
        dev=96000 if d<24 else pars.get('dev_after_T10',60000)
        fixed=cap_cost+ads+ops+dev
        compute=0
        for (g,sd,p),n in coh.items():
            up=usage.get((g,p),usage.get(('S2',p),160))
            # C quota raised modestly; power usage rises gradually
            quota_infl=1.0+(0.06 if p=='C' and d>3 else 0.0)
            compute+=n*up*cost_unit[p]*quota_infl
        compute*=1+pars.get('usage_infl',0.05)*d/84
        c-=fixed+compute+0.5*new_leads
        # billing/churn at renewals
        for key,n in list(coh.items()):
            if n<=0: continue
            g,sd,p=key
            if sd==t: continue
            if sd%30==t%30:
                age=t-sd
                promo=0.0; churn=0.03
                if g=='S1':
                    if age<45:
                        promo=8.0
                        churn=(pars.get('s1_p30_A',0.35) if p=='A' else pars.get('s1_p30_B',0.16))
                    elif age<75:
                        promo=5.0; churn=pars.get('s1_p60',0.08)
                    else:
                        churn=pars.get('s1_old',0.05)
                    if d>=15: churn*=0.80
                    if d>=24: churn*=0.55
                elif g=='S2':
                    churn=pars.get('s2_p30',0.025) if age<45 else pars.get('s2_old',0.014)
                    if d>=24: churn*=0.6
                elif g=='S3':
                    churn=pars.get('s3_p30',0.035) if age<45 else pars.get('s3_old',0.018)
                    if d>=24: churn*=0.6
                elif g=='D_S07':
                    churn=pars.get('ds07_p30',0.08) if age<45 else 0.04
                else:
                    churn=pars.get('ds10_p30',0.08) if age<45 else 0.04
                churn=max(0.002,min(0.90,churn*pars.get('churn_mult',1.0)))
                survivors=n*(1-churn)
                coh[key]=survivors
                c+=survivors*max(prices[p]-promo,0)
        outs[d]=c
    print(name,{h:round(outs[h]) for h in [7,28,84,182]})
    return outs
