./novamind-operation python-c "import novamind_api as nm; DAY=nm.vars.current_day
r=nm.query(f'''SELECT du.day, SUM(du.usage_units) units, COUNT(DISTINCT du.customer_id) users FROM daily_usage du WHERE du.day BETWEEN {DAY-6} AND {DAY} GROUP BY du.day ORDER BY du.day''')['rows']; print(r)
r=nm.query(f'''SELECT du.day,c.group_id, SUM(du.usage_units) units, COUNT(DISTINCT du.customer_id) users FROM daily_usage du JOIN customers c ON c.customer_id=du.customer_id WHERE du.day BETWEEN {DAY-6} AND {DAY} GROUP BY du.day,c.group_id ORDER BY du.day,c.group_id''')['rows'];
for row in r: print(row)
" > week32_usage.txt && cat week32_usage.txt

