import novamind_api as nm, json
DAY=nm.vars.current_day
print('DAY', DAY)

def q(sql):
    r=nm.query(sql)
    if r.get('warning'):
        print('WARNING', r['warning'])
    return r['rows']

# 1) Invest in next-gen R&D while cash flow is safely positive.
try:
    res = nm.research.start_research_project(tier=9)
    print('start T9', json.dumps(res, indent=2))
except Exception as e:
    print('start T9 error', repr(e))

# 2) Proactively scale capacity before >70M/day usage and quota/ads growth; also addresses latency variance posts.
try:
    res = nm.infrastructure.set_capacity_tier(tier=7)
    print('capacity', json.dumps(res, indent=2))
except Exception as e:
    print('capacity error', repr(e))

# 3) Raise quotas for professional workloads without changing prices or tiers.
try:
    res = nm.pricing.set_usage_quotas(A=250, B=500, C=2500)
    print('quotas', json.dumps(res, indent=2))
except Exception as e:
    print('quota error', repr(e))

# 4) Keep prices/model tiers stable.
try:
    print('prices', json.dumps(nm.pricing.set_prices(A=19, B=79, C=149), indent=2))
    print('tiers', json.dumps(nm.pricing.set_model_tiers(A=2, B=3, C=3), indent=2))
except Exception as e:
    print('price/tier error', repr(e))

# 5) Maintain global ops/dev and targeted spend; modest ops lift for S1/S3 and D_S10 as subscriber count expands.
try:
    print('daily spend', json.dumps(nm.marketing.set_daily_spend(operations=2000, development=1000), indent=2))
    print('targeted ops', json.dumps(nm.analytics.set_targeted_ops_spend(targeted_spend={
        'S1': 35000.0, 'S2': 35000.0, 'S3': 15000.0, 'D_S07': 0.0, 'D_S10': 3000.0
    }), indent=2))
    print('targeted dev', json.dumps(nm.analytics.set_targeted_dev_spend(targeted_spend={
        'S1': 0.0, 'S2': 20000.0, 'S3': 25000.0, 'D_S07': 20000.0, 'D_S10': 30000.0
    }), indent=2))
except Exception as e:
    print('ops/dev error', repr(e))

# 6) Keep in-app ads off; keep S2/S3 lead promos, remove D_S10 lead promo now that B quality is clearing its floor.
try:
    print('ads strength', json.dumps(nm.marketing.set_ads_strength(global_strength=0.0), indent=2))
    print('lead promos', json.dumps(nm.marketing.set_lead_promotion(global_promotion=0.0, by_group={
        'S1': 0.0, 'S2': 20.0, 'S3': 30.0, 'D_S07': 0.0, 'D_S10': 0.0
    }), indent=2))
except Exception as e:
    print('ads/lead promo error', repr(e))

# 7) Continue high-ROI S2/S3 content ads and run a controlled D_S10 channel test (music producers) across likely channels.
try:
    targeted_ads = {
        'content_marketing': {'S2': 45000.0, 'S3': 30000.0, 'D_S10': 5000.0},
        'social_media': {'D_S10': 5000.0},
        'search_ads': {'D_S10': 5000.0},
        'referral_program': {'D_S10': 5000.0},
        'linkedin': {}
    }
    print('targeted ads', json.dumps(nm.marketing.set_targeted_ad_spend(targeted_spend=targeted_ads), indent=2))
except Exception as e:
    print('ad spend error', repr(e))

# 8) Promotion hygiene: S1 next p30 cohorts d195-201 get $8; p60 d165-171 get $5. No blanket S1 discount.
promos = {}
counts = {'p30_A':0,'p30_B':0,'p60_A':0,'p60_B':0}
for start in range(195, 202):
    for row in q(f"""
        SELECT s.customer_id, s.plan FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id
        WHERE s.status='subscribed' AND c.group_id='S1' AND s.start_day={start} AND s.plan IN ('A','B')
    """):
        promos[str(row['customer_id'])] = 8.0
        counts[f"p30_{row['plan']}"] += 1
for start in range(165, 172):
    for row in q(f"""
        SELECT s.customer_id, s.plan FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id
        WHERE s.status='subscribed' AND c.group_id='S1' AND s.start_day={start} AND s.plan IN ('A','B')
    """):
        promos[str(row['customer_id'])] = 5.0
        counts[f"p60_{row['plan']}"] += 1
print('promo counts', counts, 'total', len(promos))
try:
    res = nm.pricing.set_promotion(global_promotion=0.0, by_group={'S1':0.0,'S2':0.0,'S3':0.0,'D_S07':0.0,'D_S10':0.0}, by_customer=promos, by_group_plan={})
    # Avoid printing 14k customer dict; print summary.
    print('promotion result summary', {k: (len(v) if isinstance(v, dict) else v) for k,v in res.items()})
except Exception as e:
    print('promotion error', repr(e))

# 9) Public response to quota/cap complaint after quota + capacity action.
try:
