arguments.content:
import novamind_api as nm, copy, math, statistics
DAY=int(nm.vars.current_day)
q=lambda sql:nm.query(sql)['rows']
cash=float(q('SELECT SUM(amount) cash FROM ledger')[0]['cash'])
print('cash',round(cash,2),'day',DAY)
START=DAY-6
prices={'A':19.0,'B':79.0,'C':149.0}
cost_unit={'A':0.002,'B':0.006,'C':0.006}
# active cohorts
rows=q('''SELECT c.group_id,s.start_day,s.plan,COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' AND c.customer_type='small' GROUP BY c.group_id,s.start_day,s.plan''')
base={(r['group_id'],int(r['start_day']),r['plan']):float(r['n']) for r in rows}
active0={}
for (g,sd,p),n in base.items(): active0[g]=active0.get(g,0)+n
print('active0',active0)
# observed plan mix last week
obs=q(f'''SELECT c.group_id,s.status,s.plan,COUNT(*) n FROM customers c JOIN subscriptions s ON c.customer_id=s.customer_id WHERE c.customer_type='small' AND c.created_day BETWEEN {START} AND {DAY} GROUP BY c.group_id,s.status,s.plan''')
def observed_mix(g, fallback):
    d={p:sum(r['n'] for r in obs if r['group_id']==g and r['status']=='subscribed' and r['plan']==p) for p in ['A','B','C']}
    tot=sum(d.values())
    return fallback if tot==0 else {p:d[p]/tot for p in d}
planmix={
    'S1': observed_mix('S1', {'A':0.78,'B':0.22,'C':0}),
    'S2': observed_mix('S2', {'A':0.18,'B':0.81,'C':0.01}),
    'S3': observed_mix('S3', {'A':0.04,'B':0.46,'C':0.50}),
    'D_S07': {'A':0.00,'B':0.92,'C':0.08},
    'D_S10': {'A':0.28,'B':0.70,'C':0.02},
}
print('planmix',planmix)
# planned paid leads/day using observed S2/S3 spend and assumptions for D tests
ad=q(f'''SELECT group_id,channel_id,SUM(leads_generated) leads,SUM(spend) spend FROM ad_channel_leads WHERE day BETWEEN {START} AND {DAY} GROUP BY group_id,channel_id''')
# aggregate S2/S3
obs_paid={}; obs_spend={}
for r in ad:
    obs_paid[r['group_id']]=obs_paid.get(r['group_id'],0)+r['leads']/7
    obs_spend[r['group_id']]=obs_spend.get(r['group_id'],0)+r['spend']/7
planned_spend={'S1':0,'S2':45000,'S3':30000,'D_S07':0,'D_S10':20000}
paid_day={}
for g in ['S1','S2','S3','D_S07','D_S10']:
    if planned_spend[g]<=0: paid_day[g]=0.0
    elif g in obs_paid and obs_spend.get(g,0)>0:
        paid_day[g]=obs_paid[g]*(planned_spend[g]/obs_spend[g])**0.82
    elif g=='D_S10':
        paid_day[g]=800.0 # controlled 20k/day multi-channel test, assumed CPL $25 blended initially
    else:
        paid_day[g]=planned_spend[g]/35
print('paid_day',paid_day,'obs_paid',obs_paid)
# organic/network leads/day last7, use late-week trend for D10
org_rows=q(f'''SELECT c.group_id,COUNT(*) leads FROM customers c WHERE c.customer_type='small' AND c.created_day BETWEEN {START} AND {DAY} AND c.acquisition_source='network' GROUP BY c.group_id''')
org_day={r['group_id']:r['leads']/7 for r in org_rows}
# D10 trend rising: use current day not weekly avg for base; D07 stays ~250-300
for r in q(f'''SELECT c.group_id,COUNT(*) leads FROM customers c WHERE c.customer_type='small' AND c.created_day={DAY} AND c.acquisition_source='network' GROUP BY c.group_id'''):
    if r['group_id']=='D_S10': org_day['D_S10']=max(org_day.get('D_S10',0), r['leads']*0.9)
for g in ['S1','S2','S3','D_S07','D_S10']: org_day.setdefault(g,0.0)
print('org_day',org_day)
# usage averages per active user/day last7 by group/plan; D caps/quotas after action uplift
usage_rows=q(f'''SELECT c.group_id,s.plan,SUM(du.usage_units) usage, COUNT(DISTINCT du.customer_id) users FROM daily_usage du JOIN subscriptions s ON s.customer_id=du.customer_id JOIN customers c ON c.customer_id=du.customer_id WHERE du.day BETWEEN {START} AND {DAY} AND s.status='subscribed' GROUP BY c.group_id,s.plan''')
usage={}
for r in usage_rows:
    usage[(r['group_id'],r['plan'])]=(r['usage']/7)/max(1,r['users'])
# baseline for new groups
for p,v in {'A':170,'B':223,'C':300}.items(): usage[('D_S07',p)]=v
for p,v in {'A':120,'B':125,'C':180}.items(): usage[('D_S10',p)]=v
print('usage S2/S3/D', {str(k):round(v,1) for k,v in usage.items() if k[0] in ['S2','S3','D_S07','D_S10']})

def init_rev(g,n):
    return n*sum(planmix[g][p]*prices[p] for p in ['A','B','C'])

def add_new(coh,g,day,n):
    for p,f in planmix[g].items():
        if f and n>0: coh[(g,day,p)]=coh.get((g,day,p),0)+n*f

def simulate(label, pars, H=182):
    coh=copy.deepcopy(base); c=cash; outs={}; done=set()
    for t in range(DAY+1, DAY+H+1):
        d=t-DAY
        active={}
        for (g,sd,p),n in coh.items(): active[g]=active.get(g,0)+n
        # future strategic investments if cash thresholds reached (T9 already spent, not repeated here)
        for tag, action_day, cost, threshold in pars.get('future_spend',[]):
            if tag not in done and t>=action_day and c>threshold:
                c-=cost; done.add(tag)
        # acquisition/leads
        new_leads=0
        for g in ['S1','S2','S3','D_S07','D_S10']:
            cap=pars.get('cap_'+g, {'S1':300000,'S2':175000,'S3':70000,'D_S07':86239,'D_S10':45386}[g])
            rawsat=max(0.03,1-(active.get(g,0)/cap)**1.35) if cap>0 else 1
            cur=max(0.03,1-(active0.get(g,0)/cap)**1.35) if active0.get(g,0)>0 else 1
            sat=rawsat/cur
            if g=='S1': sat=max(0.25,sat)
            paid=paid_day[g]*pars.get('paid_mult_'+g,1.0)
            # likely future paid D_S07 test/scale after T6 validation; D10 scale after observed channel data/T10
            if g=='D_S07' and d>=8: paid += pars.get('D07_paid_after231',300)
            if g=='D_S07' and d>=17: paid += pars.get('D07_paid_after240',900)
            if g=='D_S10' and d>=8: paid += pars.get('D10_paid_after231',400)
            if g=='D_S10' and d>=17: paid += pars.get('D10_paid_after240',800)
            org=org_day[g]*pars.get('org_mult_'+g,1.0)*(0.70+0.30*sum(active.values())/max(1,sum(active0.values())))
            conv={'S1':0.80,'S2':0.996,'S3':0.88,'D_S07':0.002,'D_S10':0.60}[g]
            if g=='D_S07':
                conv = 0.005 if d<7 else (0.35 if d<17 else 0.78)
            if g=='D_S10':
                conv = 0.55 if d<7 else (0.75 if d<17 else 0.88)
            # T10 on day240 (d=16) materially improves conversion/reputation thereafter
            if d>=17 and g in ['S2','S3','D_S07','D_S10']: conv *= pars.get('postT10_conv_boost',1.08)
            conv=max(0,min(0.995,conv*pars.get('conv_mult_'+g,1.0)))
            leads=max(0,(paid+org)*sat)
            subs=leads*conv
            new_leads+=leads
            c += init_rev(g, subs)
            add_new(coh,g,t,subs)
        # costs
        # tier7 now; ads 95k/day. Future D scaling may lift ads unless low scenario.
        cap_cost=75000
        ads=95000 + (pars.get('extra_ads_after231',10000) if d>=8 else 0) + (pars.get('extra_ads_after240',20000) if d>=17 else 0)
        ops=90000 if d<60 else pars.get('ops_later',75000)
        dev=96000 if d<17 else pars.get('dev_after_T10',65000)
        fixed=cap_cost+ads+ops+dev
        compute=0
        for (g,sd,p),n in coh.items():
            up=usage.get((g,p),usage.get(('S2',p),170))
            # quota increase and user maturity raises usage modestly
            quota_infl=1.0
            if p=='B': quota_infl += pars.get('B_quota_usage_uplift',0.05)*(1-math.exp(-d/14))
            if p=='C': quota_infl += pars.get('C_quota_usage_uplift',0.08)*(1-math.exp(-d/14))
            compute += n*up*cost_unit[p]*quota_infl
        compute *= 1+pars.get('usage_drift_84d',0.06)*d/84
        c -= fixed + compute + 0.5*new_leads
        # billing/churn/revenue at renewals
        for key,n in list(coh.items()):
            if n<=0: continue
            g,sd,p=key
            if sd==t: continue
            if sd%30==t%30:
                age=t-sd
                promo=0.0
                if g=='S1':
                    # actual p30 A erratic; d195-201 have $8, p60 d165-171 $5
                    if age<45:
                        promo=8.0; churn=pars.get('s1_p30_A',0.70) if p=='A' else pars.get('s1_p30_B',0.22)
                    elif age<75:
                        promo=5.0; churn=pars.get('s1_p60',0.10)
                    else:
                        churn=pars.get('s1_old',0.05)
                    if d>=17: churn*=0.70
                elif g=='S2':
                    churn=pars.get('s2_p30',0.035) if age<45 else pars.get('s2_old',0.015)
                    if d>=17: churn*=0.65
                elif g=='S3':
                    churn=pars.get('s3_p30',0.055) if age<45 else pars.get('s3_old',0.022)
                    if d>=17: churn*=0.65
                elif g=='D_S07':
                    churn=pars.get('d07_p30',0.06) if age<45 else 0.03
                elif g=='D_S10':
                    churn=pars.get('d10_p30',0.07) if age<45 else 0.035
                else:
                    churn=0.04
                churn=max(0.002,min(0.95,churn*pars.get('churn_mult',1.0)))
                survivors=n*(1-churn)
                coh[key]=survivors
                c += survivors*max(prices[p]-promo,0)
        outs[d]=c
    print(label,{h:round(outs[h]) for h in [7,28,84,182]}, 'spent', done)
    return outs

basepars={
    'future_spend':[('T11',252,2500000,9000000),('T12',280,3666667,16000000),('T13',320,5000000,30000000)],
    'extra_ads_after231':15000,'extra_ads_after240':25000,
    'D07_paid_after231':300,'D07_paid_after240':900,'D10_paid_after231':400,'D10_paid_after240':800,
}
low={
    'paid_mult_S2':0.70,'paid_mult_S3':0.70,'paid_mult_D_S10':0.45,'org_mult_S2':0.75,'org_mult_S3':0.75,'org_mult_D_S07':0.5,'org_mult_D_S10':0.6,
    'conv_mult_D_S10':0.65,'conv_mult_D_S07':0.55,'conv_mult_S3':0.88,'cap_S2':145000,'cap_S3':56000,'cap_D_S10':30000,'cap_D_S07':45000,
    's1_p30_A':0.90,'s1_p30_B':0.35,'s1_p60':0.16,'s1_old':0.08,'s2_p30':0.07,'s3_p30':0.10,'churn_mult':1.2,
    'usage_drift_84d':0.12,'B_quota_usage_uplift':0.08,'C_quota_usage_uplift':0.12,
    'D07_paid_after231':0,'D07_paid_after240':250,'D10_paid_after231':100,'D10_paid_after240':300,'extra_ads_after231':5000,'extra_ads_after240':5000,
    'future_spend':[('T11',300,2500000,15000000)], 'dev_after_T10':80000, 'ops_later':85000,
}
high={
    'paid_mult_S2':1.15,'paid_mult_S3':1.15,'paid_mult_D_S10':1.3,'org_mult_S2':1.25,'org_mult_S3':1.25,'org_mult_D_S07':1.7,'org_mult_D_S10':1.5,
    'conv_mult_D_S10':1.15,'conv_mult_D_S07':1.2,'conv_mult_S3':1.05,'cap_S2':220000,'cap_S3':90000,'cap_D_S10':70000,'cap_D_S07':110000,
    's1_p30_A':0.25,'s1_p30_B':0.08,'s1_p60':0.04,'s1_old':0.025,'s2_p30':0.012,'s3_p30':0.018,'churn_mult':0.75,
    'usage_drift_84d':0.035,'B_quota_usage_uplift':0.03,'C_quota_usage_uplift':0.04,
    'D07_paid_after231':800,'D07_paid_after240':1600,'D10_paid_after231':900,'D10_paid_after240':1800,'extra_ads_after231':30000,'extra_ads_after240':50000,
    'future_spend':[('T11',245,2500000,7000000),('T12',260,3666667,12000000),('T13',292,5000000,25000000),('T14',350,6666667,50000000)], 'dev_after_T10':55000, 'ops_later':65000,
}
for label,pars in [('low',low),('base',basepars),('high',high)]:
    simulate(label,pars)

