./novamind-operation python-c "import novamind_api as nm; D=nm.vars.current_day
for g in ['D_S07','D_S10','S2','S3']:
 print('GROUP',g)
 rows=nm.query(f'''SELECT c.created_day day, COUNT(*) leads, SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) sub, SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost, SUM(CASE WHEN s.status='subscribed' AND s.plan='A' THEN 1 ELSE 0 END) A, SUM(CASE WHEN s.status='subscribed' AND s.plan='B' THEN 1 ELSE 0 END) B, SUM(CASE WHEN s.status='subscribed' AND s.plan='C' THEN 1 ELSE 0 END) C, AVG(CASE WHEN s.status='subscribed' THEN s.effective_price END) avgp FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.group_id='{g}' AND c.created_day>{D-14} GROUP BY c.created_day ORDER BY c.created_day''')['rows']
 for r in rows: print(r)
"

./novamind-operation python-c "import novamind_api as nm, json
for g in ['S1','S2','S3','D_S10','D_S07']:
 print('\nGROUP',g)
 try: print(json.dumps(nm.market.get_group_insights(g), indent=2)[:6000])
 except Exception as e: print('err',e)
" > insights.txt
sed -n '1,240p' insights.txt

