import novamind_api as nm, json
results=[]
for i in range(6):
    try:
        res=nm.market.research_market()
    except Exception as e:
        res={'error':repr(e)}
    print('attempt',i+1,json.dumps(res,indent=2))
    results.append(res)
print('current_day', nm.vars.current_day)
print('overview', json.dumps(nm.market.get_market_overview(), indent=2))
# print insights for any newly discovered groups and all discovered hidden groups
rows=nm.query("SELECT group_id, info_level, discovered_day FROM group_info_levels WHERE info_level>0 AND is_discoverable=1 ORDER BY discovered_day, group_id")['rows']
for r in rows:
    gid=r['group_id']
    print('\nINSIGHTS',gid)
    try:
        print(json.dumps(nm.market.get_group_insights(group_id=gid), indent=2))
    except Exception as e: print('err',repr(e))

import novamind_api as nm, json
for gid in ['D_S04','D_E08']:
    try:
        res=nm.market.research_group(group_id=gid, target_level=3)
    except Exception as e:
        res={'error':repr(e)}
    print(gid, json.dumps(res, indent=2))
print('cash', nm.query('SELECT SUM(amount) cash FROM ledger')['rows'][0]['cash'])

