arguments.command:
./novamind-operation python-c "import novamind_api as nm
for title,sql in [('active issues', \"\"\"SELECT c.group_id, COUNT(*) n, MIN(i.open_day) oldest_day, MAX(i.open_day) newest_day, AVG(i.days_open) avg_days_open, MAX(i.days_open) max_days_open FROM issues i JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) WHERE i.status='open' AND s.status='subscribed' GROUP BY c.group_id ORDER BY n DESC\"\"\"), ('all issues', \"\"\"SELECT c.group_id, COUNT(*) n, MIN(i.open_day) oldest_day, MAX(i.open_day) newest_day, AVG(i.days_open) avg_days_open, MAX(i.days_open) max_days_open FROM issues i JOIN customers c USING(customer_id) WHERE i.status='open' GROUP BY c.group_id ORDER BY n DESC\"\"\")]:
 print('##', title)
 for row in nm.query(sql)['rows']: print(row)
print('research')
for row in nm.query('SELECT * FROM research_projects ORDER BY expected_completion_day')['rows']: print(row)
print('group info')
for row in nm.query('SELECT * FROM group_info_levels ORDER BY group_id')['rows']: print(row)
print('notifications')
for row in nm.query('SELECT * FROM notifications ORDER BY day DESC LIMIT 20')['rows']: print(row)"

