sql='''SELECT CAST((245 - s.start_day)/30 AS INT) AS months, MIN(s.start_day) min_start, MAX(s.start_day) max_start, s.plan, COUNT(*) n, AVG(s.effective_price) avg_price FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND s.status='subscribed' AND ((246 - s.start_day)%30 BETWEEN 0 AND 6 OR (247 - s.start_day)%30 BETWEEN 0 AND 6) GROUP BY months,s.plan ORDER BY months,s.plan'''
# SQL mod weird; simpler: start_day in ranges current+1-horizon - 30*m
for m in range(1,9):
 lo=246-30*m; hi=252-30*m
 rows=nm.query(f\"\"\"SELECT {m} months, s.plan, COUNT(*) n, AVG(s.effective_price) avg_price FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND s.status='subscribed' AND s.start_day BETWEEN {lo} AND {hi} GROUP BY s.plan\"\"\")['rows']
 if rows:
  print('due month',m,'start',lo,hi)
  for r in rows: print(r)
"

