import novamind_api as nm, json
cohorts=[(216,222,8.0,'p30'),(186,192,5.0,'p60'),(156,162,5.0,'p90')]
by_customer={}; counts={}
for lo,hi,disc,label in cohorts:
    counts[label]=0
    for sd in range(lo,hi+1):
        for plan in ['A','B']:
            rows=nm.query(f"""
            SELECT s.customer_id FROM subscriptions s JOIN customers c USING(customer_id)
            WHERE c.group_id='S1' AND s.status='subscribed' AND s.plan='{plan}' AND s.start_day={sd}
