import novamind_api as nm, json
print('day', nm.vars.current_day)
print('cash', nm.query('SELECT SUM(amount) cash FROM ledger')['rows'])
print('latest config history', nm.query('SELECT * FROM config_history ORDER BY day DESC LIMIT 1')['rows'])
for st in ['targeted_ad_spend','lead_promotion','promotion','targeted_ops_spend','targeted_dev_spend','ads_strength']:
 rows=nm.query(f"SELECT day, settings_json FROM config_overrides WHERE setting_type='{st}' ORDER BY id DESC LIMIT 1")['rows']
 print('\n',st)
 for r in rows: print(r['day'], r['settings_json'][:3000])
print('\nEnterprise turn row counts')
for row in nm.query("""SELECT sender, COUNT(*) n FROM enterprise_turns WHERE closed=0 GROUP BY sender""")['rows']: print(row)
print('open distinct threads/customer rows')
for row in nm.query("""SELECT c.group_id, COUNT(DISTINCT et.customer_id) customers, SUM(CASE WHEN et.sender='system' THEN et.seat_count ELSE 0 END) seats FROM enterprise_turns et JOIN customers c USING(customer_id) WHERE et.closed=0 GROUP BY c.group_id ORDER BY seats DESC""")['rows']: print(row)
print('\nResearch projects incomplete')
for row in nm.query("SELECT project_id,tier,status,started_day,expected_completion_day,expected_quality_boost FROM research_projects WHERE status!='completed' ORDER BY expected_completion_day")['rows']: print(row)
print('\nGroup info known')
for row in nm.query("SELECT group_id, info_level, discovered_day, last_research_day FROM group_info_levels WHERE info_level>0 ORDER BY group_id")['rows']: print(row)
PY
./novamind-operation python final_check_day245.py > final_check_day245.txt
sed -n '1,220p' final_check_day245.txt

