cat > analyze_week.py <<'PY'
import novamind_api as nm, json, math
print('day', nm.vars.current_day)
# cash ledger total
for q in [
"SELECT SUM(amount) as cash FROM ledger",
"SELECT category, SUM(amount) as amt, COUNT(*) as n FROM ledger WHERE day>=252 GROUP BY category ORDER BY amt",
"SELECT day, SUM(amount) as amt FROM ledger WHERE day>=252 GROUP BY day ORDER BY day",
]:
    print('\nQ', q)
    try:
        r=nm.query(q)
        for row in r['rows'][:50]: print(row)
        if r.get('truncated'): print('TRUNCATED')
    except Exception as e: print('ERR',e)
# active subscriptions by group/plan
queries=[
"""SELECT c.group_id, s.plan, COUNT(*) n, SUM(COALESCE(s.seat_count,1)) seats, SUM(s.effective_price*COALESCE(s.seat_count,1)) mrr, AVG(s.effective_price) avg_price, AVG(c.usage_per_day) avg_usage FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' GROUP BY c.group_id,s.plan ORDER BY mrr DESC""",
"""SELECT c.group_id, COUNT(*) n, SUM(COALESCE(s.seat_count,1)) seats, SUM(s.effective_price*COALESCE(s.seat_count,1)) mrr, AVG(c.usage_per_day) avg_usage FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' GROUP BY c.group_id ORDER BY mrr DESC""",
"""SELECT c.group_id, COUNT(*) cancels FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='cancelled' AND s.end_day>=252 GROUP BY c.group_id ORDER BY cancels DESC""",
"""SELECT c.group_id, COUNT(*) newsubs FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.start_day>=252 AND s.status='subscribed' GROUP BY c.group_id ORDER BY newsubs DESC""",
"""SELECT c.group_id, s.plan, COUNT(*) newsubs FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.start_day>=252 GROUP BY c.group_id,s.plan ORDER BY newsubs DESC""",
]
for q in queries:
    print('\nQ', q[:120])
    try:
        r=nm.query(q)
        for row in r['rows'][:100]: print(row)
        if r.get('truncated'): print('TRUNCATED')
    except Exception as e: print('ERR',e)
# current spend? maybe settings table? try get cost info
print('\nCOST INFO')
try:
    ci=nm.infrastructure.get_cost_info(); print(json.dumps(ci, indent=2)[:4000])
except Exception as e: print('ERR cost',e)
# enterprise open latest
q="""
WITH latest AS (
 SELECT customer_id, MAX(message_id) AS max_mid FROM enterprise_turns WHERE closed=0 GROUP BY customer_id
)
SELECT e.sender, e.day, e.group_id, COUNT(*) customers, SUM(e.seat_count) seats, AVG(e.turn_number) avg_turn, MIN(e.message_id) min_mid, MAX(e.message_id) max_mid
FROM enterprise_turns e JOIN latest l ON e.customer_id=l.customer_id AND e.message_id=l.max_mid
GROUP BY e.sender,e.day,e.group_id ORDER BY e.sender,e.day,e.group_id
"""
print('\nEnterprise latest open')
try:
    r=nm.query(q)
    for row in r['rows']: print(row)
except Exception as e: print('ERR ent',e)
# closed/subscribed enterprise count maybe customers type large active subs
q="""SELECT c.group_id, COUNT(DISTINCT s.customer_id) n, SUM(s.seat_count) seats, SUM(s.effective_price*s.seat_count) mrr FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' AND c.customer_type='large' GROUP BY c.group_id"""
print('\nEnterprise subs')
try:
    r=nm.query(q); print(r['rows'])
except Exception as e: print('ERR entsub',e)
# issues active sub ages by group
q="""SELECT c.group_id, COUNT(*) issues, AVG(i.day_created) avg_created, MIN(i.day_created) oldest_day, MAX(i.day_created) newest_day, SUM(CASE WHEN (? - i.day_created)>1 THEN 1 ELSE 0 END) older1, SUM(CASE WHEN (? - i.day_created)>2 THEN 1 ELSE 0 END) older2 FROM issues i JOIN subscriptions s ON i.customer_id=s.customer_id AND s.status='subscribed' JOIN customers c ON i.customer_id=c.customer_id WHERE i.status='open' GROUP BY c.group_id ORDER BY issues DESC""".replace('?', str(nm.vars.current_day))
print('\nOpen issues active subs')
try:
    r=nm.query(q)
    for row in r['rows']: print(row)
except Exception as e: print('ERR issues',e)
# social posts last 14
print('\nSOCIAL')
try:
    posts=nm.analytics.get_social_posts(days=14, limit=30); print(json.dumps(posts, indent=2)[:8000])
except Exception as e: print('ERR social',e)
# market overview maybe l3
print('\nMARKET OVERVIEW')
try:
    ov=nm.market.get_market_overview(); print(json.dumps(ov, indent=2)[:20000])
except Exception as e: print('ERR market',e)
# research projects
print('\nRESEARCH')
try:
    pr=nm.research.list_research_projects(); print(json.dumps(pr, indent=2)[:12000])
except Exception as e: print('ERR research',e)
PY
