cat > usage_week37.py <<'PY'
import novamind_api as nm
D=nm.vars.current_day
qs={
'usage7_group_plan': f"""SELECT c.group_id,s.plan,COUNT(DISTINCT du.customer_id) users,SUM(du.usage_units) usage7,AVG(du.usage_units) avg_record FROM daily_usage du JOIN subscriptions s ON du.customer_id=s.customer_id AND s.status='subscribed' JOIN customers c ON du.customer_id=c.customer_id WHERE du.day BETWEEN {D-6} AND {D} GROUP BY c.group_id,s.plan ORDER BY usage7 DESC""",
'usage_day259_group_plan': f"""SELECT c.group_id,s.plan,COUNT(DISTINCT du.customer_id) users,SUM(du.usage_units) usage,AVG(du.usage_units) avg_usage_per_record FROM daily_usage du JOIN subscriptions s ON du.customer_id=s.customer_id AND s.status='subscribed' JOIN customers c ON du.customer_id=c.customer_id WHERE du.day={D} GROUP BY c.group_id,s.plan ORDER BY usage DESC""",
'usage7_total': f"SELECT SUM(usage_units) usage FROM daily_usage WHERE day BETWEEN {D-6} AND {D}",
'usage_by_day': f"SELECT day, SUM(usage_units) usage, COUNT(DISTINCT customer_id) users FROM daily_usage WHERE day BETWEEN {D-6} AND {D} GROUP BY day ORDER BY day",
}
for name,q in qs.items():
 print('\n---',name,'---')
 try:
  r=nm.query(q)
  for row in r['rows'][:100]: print(row)
 except Exception as e: print('ERR',e)
PY
./novamind-operation python usage_week37.py > week37_usage.txt
cat week37_usage.txt

